  assert.equal(large.headers.get('location'), 'https://covers.example.com/9780061054884-large.jpg')
})

test('cover rejects an invalid size', async () => {
  const res = await fetch(`${base}/api/books/b1/cover/huge`)
  assert.equal(res.status, 400)
  assert.deepEqual(await res.json(), { error: 'invalid size' })
})

